def classify_lag(lag):
    if 'lag' not in inputs:
        result = {'kind': 'missing', 'lag': None}
    else:
        lag = inputs['lag']
        if lag is None:
            result = {'kind': 'null', 'lag': None}
        elif type(lag) is int and not type(lag) is bool and 5 <= lag <= 14:
            result = {'kind': 'integer', 'lag': lag}
        else:
            result = {'kind': 'invalid', 'lag': None}
    return result
